DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT104-S1-Q2$batch01$ AND q.stimulus=$batch01$Although 90 percent of the population believes itself to be well informed about health care, only 20 percent knows enough about DNA to understand a news story about DNA. So apparently at least 80 percent of the population does not know enough about medical concepts to make well-informed personal medical choices or to make good public policy decisions about health care.$batch01$ AND q.prompt=$batch01$The argument's reasoning is questionable because the argument fails to demonstrate that$batch01$ AND q.correct_choice=$batch01$D$batch01$) THEN RAISE EXCEPTION 'Question changed: PT104-S1-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT104-S1-Q2$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT104-S1-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT104-S1-Q2$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$Those people who can understand news stories about DNA are able to make well-informed personal medical choices$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT104-S1-Q2 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT104-S1-Q2$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$More than 20 percent of the population needs to be well informed about health care for good public policy decisions about health care to be made$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT104-S1-Q2 B'; END IF; END $guard$;
